import {refreshEntryIndex} from '../../core/thought-model.js';
import {MemoryService} from '../../core/memory/service.js';
// Valid synthetic Thought-layer shapes; no Source/Input text, fixture stays out of packages.
export async function seedMemoryScale(s,count){await s.finishFoundation();const existing=await s.repository.transaction(false,t=>t.count('topics'));let base;if(!existing){const topic=await s.createTopic({operationId:crypto.randomUUID(),name:'规模模板'}),entry=await s.createEntry({operationId:crypto.randomUUID(),actor:'user',body:'规模模板',type:'idea',formation:'explicit',evidence:[]});await s.placeEntry({operationId:crypto.randomUUID(),topicId:topic.id,entryId:entry.id,expectedEntryRevision:entry.revision,expectedTopicRevision:(await s.topic(topic.id)).organizationRevision});base=await s.repository.transaction(false,async t=>({topic:await t.get('topics',topic.id),section:await t.get('sections',JSON.stringify([topic.id,1,topic.sectionId])),entry:await t.get('thoughts',entry.id),placement:await t.get('placements',JSON.stringify([topic.id,1,entry.id]))}));await s.repository.transaction(true,async t=>{await t.delete('topics',base.topic.id);await t.delete('sections',base.section.id);await t.delete('thoughts',base.entry.id);await t.delete('placements',base.placement.id);await t.put('meta',{id:'synthetic-memory-scale-template',value:base});});}else base=(await s.repository.transaction(false,t=>t.get('meta','synthetic-memory-scale-template'))).value;
 const start=existing;for(let i=start;i<count;i+=50){await s.repository.transaction(true,async t=>{for(let n=i;n<Math.min(count,i+50);n++){const id='memory-scale-topic-'+String(n).padStart(4,'0'),sectionId='memory-scale-section-'+n,topic={...base.topic,id,name:n%6===0?'PAIA 产品计划 '+n:'虚构长期主题 '+n,nameKey:'memory '+n,defaultSectionId:sectionId,sourceRecordIds:[],activeLayoutGeneration:1,layoutJobId:null,negativeUpdatedSequence:-n};await t.put('topics',topic);await t.put('sections',{...base.section,id:JSON.stringify([id,1,sectionId]),topicId:id,sectionId,sourceRecordIds:[]});for(let j=0;j<5;j++){const entryId=id+'-entry-'+j,e={...base.entry,id:entryId,title:'当前工作记录 '+j,thoughtText:`MEMORY_TARGET_${String(n).padStart(4,'0')} · PAIA 合成计划 ${j}。`+'这是一段用于本地预算与检索测试的虚构正文。'.repeat(40),sourceRecordIds:[],inputRefs:[],topics:[id],updatedSequence:n*5+j+1,createdSequence:n*5+j+1,revision:0,contentRevision:0};refreshEntryIndex(e);await t.put('thoughts',e);await t.put('placements',{...base.placement,id:JSON.stringify([id,1,entryId]),topicId:id,entryId,sectionId,rank:String((j+1)*1024).padStart(12,'0'),sourceRecordIds:[]});}}});await new Promise(r=>setTimeout(r,0));}const memory=new MemoryService(s);const topicIds=Array.from({length:count},(_,n)=>'memory-scale-topic-'+String(n).padStart(4,'0'));await memory.authorize({topicIds,decision:'allowed',confirmed:true});return {topics:count,entries:count*5};}
